               const vector<ll>& rightPrefix,
               char target) {
    const ll rightSize = static_cast<ll>(right.size());
    ll count = leftPrefix[leftLength];

    if (rightStart < rightSize)
        count += rightPrefix[rightSize] - rightPrefix[rightStart + 1];

    if (leftLength > 0 && rightStart < rightSize)
