#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using Operation = pair<ll, ll>;
using Operations = vector<Operation>;

vector<ll> changes(const string& s, char expected) {
    vector<ll> result;
    result.reserve(s.size());

    char last = expected;
    for (ll i = static_cast<ll>(s.size()) - 1; i >= 0; --i) {
        if (s[static_cast<size_t>(i)] != last) {
            last = s[static_cast<size_t>(i)];
            result.push_back(i + 1);
        }
    }
    return result;
}

Operations basicSolve(const string& a, const string& b) {
    vector<ll> p = changes(a, 'a');
    vector<ll> q = changes(b, 'b');

    const size_t count = max(p.size(), q.size());
    p.resize(count, 0);
    q.resize(count, 0);

    Operations result;
    result.reserve(count);

    for (size_t i = 0; i < count; ++i) {
        result.emplace_back(p[i], q[i]);
        swap(p, q);
    }

    return result;
}

struct TransitionInfo {
    const string& s;
    vector<ll> prefix;

    explicit TransitionInfo(const string& str) : s(str), prefix(str.size() + 1, 0) {
        for (size_t i = 2; i <= str.size(); ++i) {
            prefix[i] = prefix[i - 1] + (str[i - 1] != str[i - 2]);
        }
    }

    ll internalTransitions(size_t left, size_t right) const {
        if (right - left <= 1) return 0;
        return prefix[right] - prefix[left + 1];
    }
};

ll concatenatedChangeCount(
    const TransitionInfo& first, size_t firstLeft, size_t firstRight,
    const TransitionInfo& second, size_t secondLeft, size_t secondRight,
    char expected
) {
    const bool hasFirst = firstLeft < firstRight;
    const bool hasSecond = secondLeft < secondRight;

    if (!hasFirst && !hasSecond) return 0;

    ll result = 0;

    if (hasFirst) {
        result += first.internalTransitions(firstLeft, firstRight);
    }
    if (hasSecond) {
        result += second.internalTransitions(secondLeft, secondRight);
    }
    if (hasFirst && hasSecond) {
        result += first.s[firstRight - 1] != second.s[secondLeft];
    }

    const char last = hasSecond ? second.s[secondRight - 1]
                                : first.s[firstRight - 1];
    result += last != expected;

    return result;
}

Operations solve(const string& a, const string& b) {
    Operations result = basicSolve(a, b);

    vector<ll> p = changes(a, 'a');
    vector<ll> q = changes(b, 'b');

    ll difference = static_cast<ll>(p.size()) - static_cast<ll>(q.size());
    difference /= 2;

    p.push_back(0);
    q.push_back(0);

    const TransitionInfo infoA(a);
    const TransitionInfo infoB(b);

    for (ll i = 0; i <= 40; ++i) {
        for (ll j = 0; j <= 20; ++j) {
            ll u = llabs(difference) - 2 + i;
            ll v = j;

            if (difference < 0) {
                swap(u, v);
            }

            if (u < 0 || v < 0 ||
                u >= static_cast<ll>(p.size()) ||
                v >= static_cast<ll>(q.size())) {
                continue;
            }

            u = static_cast<ll>(p.size()) - u - 1;
            v = static_cast<ll>(q.size()) - v - 1;

            const size_t x = static_cast<size_t>(p[u]);
            const size_t y = static_cast<size_t>(q[v]);

            const ll firstCount = concatenatedChangeCount(
                infoB, 0, y,
                infoA, x, a.size(),
                'a'
            );

            const ll secondCount = concatenatedChangeCount(
                infoA, 0, x,
                infoB, y, b.size(),
                'b'
            );

            const size_t candidateSize =
                static_cast<size_t>(max(firstCount, secondCount)) + 1;

            if (candidateSize >= result.size()) {
                continue;
            }

            string a2;
            string b2;
            a2.reserve(y + a.size() - x);
            b2.reserve(x + b.size() - y);

            a2.append(b, 0, y);
            a2.append(a, x, string::npos);

            b2.append(a, 0, x);
            b2.append(b, y, string::npos);

            Operations tail = basicSolve(a2, b2);
            Operations candidate;
            candidate.reserve(tail.size() + 1);
            candidate.emplace_back(static_cast<ll>(x), static_cast<ll>(y));
            candidate.insert(candidate.end(), tail.begin(), tail.end());

            result = move(candidate);
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    Operations first = solve(s, t);
    Operations second = solve(t, s);

    cout << min(first.size(), second.size()) << '\n';

    if (second.size() < first.size()) {
