    const string& prefixString,
    ll prefixLength,
    const vector<ll>& prefixChanges,
    const string& suffixString,
    ll suffixStart,
    const vector<ll>& suffixChanges,
    char expected
) {
    const ll suffixSize = static_cast<ll>(suffixString.size());
    const bool hasPrefix = prefixLength > 0;
    const bool hasSuffix = suffixStart < suffixSize;

